package com.kvs.communication.config;

/**
 * Permission checks for this service's endpoints: CommunicationPerms.X is "hasAuthority('<code>')" for @PreAuthorize.
 * Generated by database/rbac/rewrite_preauthorize.py from the RBAC catalogue (ms-core rbac/permissions.json);
 * which roles hold each code is decided by the catalogue and by each school's custom roles, not here.
 */
public final class CommunicationPerms {

    private CommunicationPerms() {
    }

    public static final String ABSENCE_ALERTS_MANAGE = "hasAuthority('communication.absence-alerts.manage')";
    public static final String ABSENCE_ALERTS_VIEW = "hasAuthority('communication.absence-alerts.view')";
    public static final String BROADCASTS_2_MANAGE = "hasAuthority('communication.broadcasts-2.manage')";
    public static final String BROADCASTS_MANAGE = "hasAuthority('communication.broadcasts.manage')";
    public static final String BROADCASTS_VIEW = "hasAuthority('communication.broadcasts.view')";
    public static final String COMMUNITY_2_MANAGE = "hasAuthority('communication.community-2.manage')";
    public static final String COMMUNITY_MANAGE = "hasAuthority('communication.community.manage')";
    public static final String DOCUMENTS_MANAGE = "hasAuthority('communication.documents.manage')";
    public static final String GATE_PASSES_2_MANAGE = "hasAuthority('communication.gate-passes-2.manage')";
    public static final String GATE_PASSES_MANAGE = "hasAuthority('communication.gate-passes.manage')";
    public static final String GATE_PASSES_VIEW = "hasAuthority('communication.gate-passes.view')";
    public static final String MESSAGES_MANAGE = "hasAuthority('communication.messages.manage')";
    public static final String MESSAGES_VIEW = "hasAuthority('communication.messages.view')";
    public static final String MOBILE_MANAGE = "hasAuthority('communication.mobile.manage')";
    public static final String MOBILE_VIEW = "hasAuthority('communication.mobile.view')";
    public static final String STAFF_ALERTS_MANAGE = "hasAuthority('communication.staff-alerts.manage')";
    public static final String VISITORS_MANAGE = "hasAuthority('communication.visitors.manage')";
    public static final String VISITORS_VIEW = "hasAuthority('communication.visitors.view')";

    /** Open to every signed-in user (no permission needed) */
    public static final String ANY_AUTHENTICATED = "isAuthenticated()";

    /** Not an endpoint check: read any parent's app records, not only one's own (ParentAccessGuard) */
    public static final String PARENTS_ANY_PARENT = "communication.parents.any-parent";
}
